// Source-pinned review reproduction using exact repository TypeScript after Node's type transform.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { stripTypeScriptTypes } from 'node:module';
const repo = process.argv[2] ?? '/workspace/scratch/0bed53303053/GhostPay';
const ref = 'b1327d4d0e263fdfc7d4fb0b5546b18de2d7434e';
const show = (path) => execFileSync('git', ['-C', repo, 'show', `${ref}:${path}`], { encoding: 'utf8' });
const moduleUrl = (source) => `data:text/javascript;base64,${Buffer.from(source).toString('base64')}`;
const errors = moduleUrl(stripTypeScriptTypes(show('apps/relayer/src/errors.ts'), { mode: 'transform' }));
const source = stripTypeScriptTypes(show('apps/relayer/src/lane.ts'), { mode: 'transform' }).replace("'./errors.js'", JSON.stringify(errors));
const { ChainLane } = await import(moduleUrl(source));
const lane = new ChainLane(4, 1);
const releasedTicket = lane.reserve('client-one');
releasedTicket.release();
const liveTicket = lane.reserve('client-one');
let ran = false;
const value = await releasedTicket.submit(async () => { ran = true; return { value: 'stale-ticket-executed', settled: Promise.resolve() }; });
await lane.drain();
assert.equal(ran, true);
assert.equal(value, 'stale-ticket-executed');
assert.equal(lane.heldClients, 1);
console.log(JSON.stringify({ ref, ran, value, heldClients: lane.heldClients, finding: 'Released ticket still executes while another ticket occupies its client slot.' }));
liveTicket.release();
